// GitHub pulse digest (#402) — a one-paragraph factual summary banner of a repo's last-14-day
// activity. Extracted from GitHubPulse's inline card into its own composable record; adds the
// loading + empty states the inline version didn't have.
import { Row } from "@/shared/ui/layout/Row";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";
import { Card } from "@/shared/ui/data/Card";
import { Skeleton } from "@/shared/ui/feedback/Skeleton";

export interface PulseKpis { commitsWeek: number; prsMerged: number; netLines: number; passRate: number; reviewLatencyH: number; contributors: number; botShare: number }
export interface ChurnArea { area: string; add: number; del: number; files: number; color: string }
export interface CiHealth { passed: number; failed: number; cancelled: number; runs: number; passRate: number; avgMin: number }

const DEMO_KPIS: PulseKpis = { commitsWeek: 38, prsMerged: 9, netLines: 1240, passRate: 92, reviewLatencyH: 5, contributors: 4, botShare: 12 };
const DEMO_AREAS: ChurnArea[] = [{ area: "src/features/fleet", add: 820, del: 240, files: 9, color: "var(--accent)" }];
const DEMO_CI: CiHealth = { passed: 44, failed: 3, cancelled: 1, runs: 48, passRate: 92, avgMin: 6 };

export function PulseDigest({
  kpis = DEMO_KPIS, churnAreas = DEMO_AREAS, ci = DEMO_CI, partialDiffs = false, loading = false,
}: {
  kpis?: PulseKpis; churnAreas?: ChurnArea[]; ci?: CiHealth; partialDiffs?: boolean; loading?: boolean;
}) {
  const hottest = churnAreas[0];
  if (loading) {
    return (
      <Card style={{ padding: "13px 18px", marginBottom: 14 }}>
        <Row gap={8} align="baseline" style={{ marginBottom: 8 }}>
          <Skeleton w={22} h={22} radius={7} />
          <Skeleton w={140} h={10} />
        </Row>
        <Skeleton w="100%" h={32} radius={6} />
      </Card>
    );
  }
  if (churnAreas.length === 0 || (kpis.commitsWeek === 0 && kpis.prsMerged === 0)) {
    return (
      <Card style={{ padding: "20px 12px", marginBottom: 14, textAlign: "center" }}>
        <Text as="h2" mono size={12.5} weight={600} style={{ margin: 0 }}>No activity yet</Text>
        <Text as="p" style={{ margin: "6px 0 0", color: "var(--fg-muted)", fontSize: 11, lineHeight: 1.55 }}>
          The digest appears once this repo has commits or merged PRs in the window.
        </Text>
      </Card>
    );
  }
  return (
    <Card style={{
      padding: "13px 18px", marginBottom: 14,
      background: "linear-gradient(135deg, color-mix(in oklch, var(--accent), transparent 88%), var(--bg-panel) 60%)",
      border: "1px solid var(--accent-dim)",
    }}>
      <Row gap={12} align="stretch">
        <Row className="mono" justify="center" style={{
          flexShrink: 0, width: 28, height: 28, borderRadius: 7,
          background: "linear-gradient(135deg, var(--accent), oklch(0.62 0.14 50))",
          color: "#1a120a", fontWeight: 700, fontSize: 13,
        }}>G</Row>
        <Box style={{ flex: 1, fontSize: 12, lineHeight: 1.6, color: "var(--fg-muted)" }}>
          <Row align="baseline" gap={8} style={{ marginBottom: 3 }}>
            <Text as="span" mono size={11} tone="accent" style={{ textTransform: "uppercase", letterSpacing: ".06em" }}>repo pulse · last 14 days</Text>
            <Box as="span" className="hint">live from the GitHub API</Box>
          </Row>
          <Text as="p" style={{ margin: 0 }}>
            <Text weight={700} style={{ color: "var(--fg)" }}>{kpis.commitsWeek} commits</Text> and <Text weight={700} style={{ color: "var(--fg)" }}>{kpis.prsMerged} merged PRs</Text> in the last 7 days
            {kpis.contributors > 0 && <> across <Text weight={700} style={{ color: "var(--fg)" }}>{kpis.contributors} contributors</Text> ({kpis.botShare}% bot)</>}.
            CI pass rate is <Text weight={700} tone={ci.passRate >= 90 ? "success" : "danger"}>{ci.passRate}%</Text>.
            {hottest && <> Hottest area: <Text weight={700} style={{ color: "oklch(0.7 0.12 290)" }}>{hottest.area}</Text>.</>}
            {partialDiffs && <Box as="span" className="hint"> · line/churn panels reflect the most recent commits</Box>}
          </Text>
        </Box>
      </Row>
    </Card>
  );
}
